[Flags]
internal enum CoreCourierAcceptedSteps
{
    None = 0, Dispatched = 1, ReplyPrepared = 2, Arrived = 4, Payload = 8,
    DeliveryHistory = 16, Actions = 32, ReplyHistory = 64, ReplyDelivered = 128, ContentsReturned = 256
}
internal enum CoreCourierTransportOutcome { NotStarted, InTransit, Returned, Destroyed, Missing, Unconfirmed }

// Independent stages: a reply may be prepared before arrival, but is not public until delivery.
internal sealed class CoreCourierReceipt
{
    internal CoreCourierReceipt(CoreCourierAcceptedSteps accepted, CoreCourierTransportOutcome transport)
    { Accepted = accepted; Transport = transport; }
    internal CoreCourierAcceptedSteps Accepted { get; }
    internal CoreCourierTransportOutcome Transport { get; }
    internal bool Has(CoreCourierAcceptedSteps step) => (Accepted & step) == step;
    internal bool Complete => Transport == CoreCourierTransportOutcome.Returned
        && Has(CoreCourierAcceptedSteps.Dispatched | CoreCourierAcceptedSteps.ReplyPrepared
            | CoreCourierAcceptedSteps.Arrived | CoreCourierAcceptedSteps.Payload | CoreCourierAcceptedSteps.DeliveryHistory
            | CoreCourierAcceptedSteps.Actions | CoreCourierAcceptedSteps.ReplyHistory
            | CoreCourierAcceptedSteps.ReplyDelivered | CoreCourierAcceptedSteps.ContentsReturned);
}

internal void RecordCourierProgress(CoreCourierReceipt receipt, string deliveredReply = null)
{
    lock (_gate)
    {
        if (Channel != CoreDialogueChannel.Courier || _snapshot.State != CoreDialogueState.Running || receipt == null) return;
        _courierReceipt = receipt;
        if (receipt.Has(CoreCourierAcceptedSteps.ReplyDelivered) && deliveredReply != null)
            _deliveredCourierReply = deliveredReply;
        _snapshot = Result(CoreDialogueState.Running, _snapshot.Effects, _snapshot.ReasonCode);
    }
}

internal CoreDialogueOperation SubmitCourier(string contextTicket, string requestId, string playerText)
    => SubmitForContext(CoreDialogueChannel.Courier, contextTicket, requestId, playerText,
        CourierDeliveryBehavior.SubmitModuleCourierDialogue);

internal string CaptureCourierContextTicket()
{
    lock (_gate) if (_disposed) return null;
    string ticket = CourierDeliveryBehavior.IssueModuleCourierTicket(ClientId);
    if (ticket == null) return null;
    lock (_gate) if (!_disposed) return ticket;
    CourierDeliveryBehavior.RevokeModuleCourierTickets(ClientId);
    return null;
}

}

/// <summary>Courier transport outcome, independent of accepted dialogue effects.</summary>
public enum AfCourierTransportOutcome
{
    NotStarted = 0,
    InTransit = 1,
    Returned = 2,
    Destroyed = 3,
    Missing = 4,
    Unconfirmed = 5
}

/// <summary>
/// Immutable, game-object-free Courier observations. Stages need not occur in property order:
/// a reply may be prepared before arrival. False means not confirmed, not proof of rollback.
/// Overall success is reported only by AfDialogueResult.State after required return cleanup.
/// </summary>
public sealed class AfCourierReceipt
{
    public AfCourierTransportOutcome Transport { get; }
    public bool Dispatched { get; }
    public bool ReplyPrepared { get; }
    public bool Arrived { get; }
    public bool PayloadAccepted { get; }
    public bool DeliveryHistoryAccepted { get; }
    public bool ActionsAccepted { get; }
    public bool ReplyHistoryAccepted { get; }
    public bool ReplyDelivered { get; }
    public bool ContentsReturned { get; }

    internal AfCourierReceipt(AfCourierTransportOutcome transport, bool dispatched, bool replyPrepared,
        bool arrived, bool payloadAccepted, bool deliveryHistoryAccepted, bool actionsAccepted,
        bool replyHistoryAccepted, bool replyDelivered, bool contentsReturned)
    {
        Transport = transport; Dispatched = dispatched; ReplyPrepared = replyPrepared;
        Arrived = arrived; PayloadAccepted = payloadAccepted; DeliveryHistoryAccepted = deliveryHistoryAccepted;
        ActionsAccepted = actionsAccepted; ReplyHistoryAccepted = replyHistoryAccepted;
        ReplyDelivered = replyDelivered; ContentsReturned = contentsReturned;
    }

/// <summary>Main-thread capture of the existing fully prepared Courier UI draft; null means unavailable. Does not dispatch.</summary>
public string CaptureCourierContextTicket() => _client.CaptureCourierContextTicket();
/// <summary>
/// Claim a Courier draft from any thread. Completion may span many Campaign ticks and requires actual reply delivery.
/// Cancellation only wins before dispatch; disposal/load/retirement never promises network abort or effect rollback.
/// </summary>
public AfDialogueOperation SubmitCourier(string contextTicket, string requestId, string playerText)
    => new AfDialogueOperation(_client.SubmitCourier(contextTicket, requestId, playerText));

internal static AfCourierReceipt Courier(CoreCourierReceipt source)
{
    if (source == null) return null;
    return new AfCourierReceipt(
        transport: CourierTransport(source.Transport),
        dispatched: source.Has(CoreCourierAcceptedSteps.Dispatched),
        replyPrepared: source.Has(CoreCourierAcceptedSteps.ReplyPrepared),
        arrived: source.Has(CoreCourierAcceptedSteps.Arrived),
        payloadAccepted: source.Has(CoreCourierAcceptedSteps.Payload),
        deliveryHistoryAccepted: source.Has(CoreCourierAcceptedSteps.DeliveryHistory),
        actionsAccepted: source.Has(CoreCourierAcceptedSteps.Actions),
        replyHistoryAccepted: source.Has(CoreCourierAcceptedSteps.ReplyHistory),
        replyDelivered: source.Has(CoreCourierAcceptedSteps.ReplyDelivered),
        contentsReturned: source.Has(CoreCourierAcceptedSteps.ContentsReturned));
}

private static AfCourierTransportOutcome CourierTransport(CoreCourierTransportOutcome value)
{
    switch (value)
    {
        case CoreCourierTransportOutcome.NotStarted: return AfCourierTransportOutcome.NotStarted;
        case CoreCourierTransportOutcome.InTransit: return AfCourierTransportOutcome.InTransit;
        case CoreCourierTransportOutcome.Returned: return AfCourierTransportOutcome.Returned;
        case CoreCourierTransportOutcome.Destroyed: return AfCourierTransportOutcome.Destroyed;
        case CoreCourierTransportOutcome.Missing: return AfCourierTransportOutcome.Missing;
        default: return AfCourierTransportOutcome.Unconfirmed;
    }
}
